// The community loop end to end, on a simulated club.
// Simulated club: members and requests generated by code (seed 7). The pipeline, gates and rollback are real.
//   collect   simulated members (population.js, seed 7) say about a dozen ideas in their own words, three of them
//             hostile (an injection, a data export, skipping approval), with /improve on or off, through the real
//             signals: counts, an unmet request kept in the member's own record, Muse Glimmer's paraphrase checked by
//             code, a yes or a no per item, and the guards (Llama Guard 3 on the CPU)
//   cluster   DRAMA on the CPU, the 5-member threshold, weekday and weekend support, the feature catalog, sock puppets
//   specs     Muse Glimmer summarizes each idea and drafts its spec from the summary; the review classifies and checks
//   vote      quadratic votes, 9 credits a month
//   ship      the top C0 change to the beta canary, a week of simulated signals, the flags' monitor (promoted)
//   rollback  a planted bad C0 change (in range) shipped the same way; the beta members' 👎 rises; the monitor turns it off
//   forget    /forget for members who shared; their items, votes and counts go, and the cluster shrinks
//   privacy   no player id, no member's name and no body-log canary marker anywhere in the loop's data
// The guards as configured by default: Llama Guard 3 and Prompt Guard 2 both required (LOOP_GUARDS), on the CPU. And
// once more with Llama Guard down, to show the screen fails closed: every item waits.
//   flock /tmp/serve-gpu.lock node test/loop_eval.mjs [data/loop_eval.json]
// The parts of other modules (loop/review.js, flags.js, gates.js) are used when they are on the branch; otherwise their
// stand-ins (loop/parts.js), which fail closed, and the output says which.
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";

const OUT = process.argv[2] || "data/loop_eval.json", D = path.resolve(process.env.LOOP_EVAL_DIR || "data/loop-eval");
fs.rmSync(D, { recursive: true, force: true }); fs.mkdirSync(D, { recursive: true });
const N = +(process.env.LOOP_EVAL_MEMBERS || 60), SEED = +(process.env.LOOP_EVAL_SEED || 7), ARM = process.env.LOOP_EVAL_GUARDS || "llama-guard,prompt-guard";
Object.assign(process.env, { LOOP_DIR: `${D}/loop`, STORE_FILE: `${D}/players.json`, LEDGER_FILE: `${D}/ledger.jsonl`, TRACE_FILE: `${D}/traces.jsonl`, MEMORY_FILE: `${D}/memory.json`,
  SIM_MEMBERS: String(N), SIM_SEED: String(SEED), LOOP_SIMULATED: "1", LOOP_GUARDS: ARM, LOOP_CANARY_DAYS: process.env.LOOP_CANARY_DAYS || "7" });
// DRAMA's weights are on the NAS (memory.js reads REEL_HF_CACHE); Prompt Guard 2's are in the default cache, so
// HF_HUB_CACHE stays unset (its worker would read it)
process.env.REEL_HF_CACHE ||= "/mnt/nas/shuttlecoach-meta/hf";
process.env.HF_HUB_OFFLINE ||= "1"; // the guard and embedder weights are in the cache; no network
process.env.PROMPT_GUARD_TIMEOUT_MS ||= "60000";
// eight members share at once and Llama Guard answers two at a time on the CPU: it gets longer than in chat
process.env.GUARD_TIMEOUT_MS ||= "30000";
// the gates a C0 change passes here: the ones that need no GPU (the suites on the GPU are the maintainer's to run)
process.env.LOOP_SHIP_GATES ||= "policy,scan,unit,oracle,privacy";
// the loop's secret, made from the seed (simulated members only): the same members fall in the canary on every run
fs.mkdirSync(process.env.LOOP_DIR, { recursive: true });
fs.writeFileSync(path.join(process.env.LOOP_DIR, "secret"), crypto.createHash("sha256").update(`serve loop_eval seed ${SEED}`).digest("hex"), { mode: 0o600 });
const t00 = Date.now();
const signals = await import("../src/loop/signals.js");
const proposals = await import("../src/loop/proposals.js");
const { cycle, reviewSpec, shipSpec, watch } = await import("../src/loop/cycle.js");
const parts = await (await import("../src/loop/parts.js")).load();
const store = await import("../src/store.js");
const ledger = await import("../src/ledger.js");
const guardMod = await import("../src/guard.js"), { stopWorker } = guardMod;
const memory = await import("../src/memory.js");
// the club's notes the flags make, kept with the ideas (as server.js does)
try { parts.flags.onNote?.((n) => proposals.addNote(n)); } catch { /* the stand-in */ }
const LABEL = `Simulated club: members and requests generated by code (seed ${SEED}). The pipeline, gates and rollback are real.`;
console.log(`${LABEL}\nparts in use: ${["review", "flags", "gates", "builder"].map((p) => `${p} ${parts.stubs.includes(p) ? "(stand-in)" : ""}`.trim()).join(", ")}`);

// ---- the club (test/sim/loop_club.mjs: members, the twelve ideas, who says what and when) ----
const { rng, simClub, IDEAS } = await import("./sim/loop_club.mjs");
const R = rng(SEED * 7919 + 1);
// the simulated month ends weeks before the run, so nothing the run itself logs (its own guard calls) falls in a window
const DAY = 864e5, HOUR = 36e5, T0 = Date.UTC(2026, 8, 7, 4, 0); // 12:00 in Taipei, the simulated first day
const { people, hostile, normal, supports, pick, shuffle } = simClub({ seed: SEED, members: N, R, T0, DAY, HOUR });
for (const p of people) store.link(p.id, p.name);
for (const p of people) if (p.consent) signals.consent(p.id, true, { now: T0 - DAY });
// a canary marker in one member's body log: it must never show up in the loop's data
// (the flags' privacy canary, loop/flags.js plantMarker: also watched in every request to an outside host)
let MARKER;
try { const m = parts.flags.plantMarker(normal[0].id); MARKER = m.marker; store.update(normal[0].id, (q) => { q.body.log.push(m.entry); }); }
catch { MARKER = `zq${crypto.randomBytes(9).toString("hex")}`; store.update(normal[0].id, (q) => { q.body.log.push({ id: "b-canary", at: new Date(T0).toISOString(), part: "knee", side: "right", kind: "sore", level: 2, note: `knee ${MARKER}` }); }); }

// Prompt Guard 2 loads its weights on the first call: warmed up here, so the first items do not wait for it
const warm = await guardMod.injected(["Ask about games later in the day"], { timeoutMs: 180000 });
console.log(`Prompt Guard 2: ${warm[0]?.injected === false ? "ready" : `not ready (${warm[0]?.error || "?"})`}`);
// ---- 1. collect: the real signals, one member at a time, four members at once (the model's slots) ----
const rows = [];
async function one(s) {
  const row = { idea: s.idea, hostile: s.hostile, kind: s.kind, raw: s.text };
  rows.push(row);
  if (s.kind === "unmet") {
    if (!signals.consented(s.p.id)) return (row.stage = "no consent");
    signals.record(s.p.id, { kind: "unmet", source: s.source, text: s.text }, { now: s.at });
  }
  const off = await signals.offerShare(s.p.id, { kind: s.kind, text: s.text, source: s.source }, { now: s.at, profile: { group: s.p.group, band: s.p.band } });
  if (!off.id) { row.stage = "not offered"; row.why = off.why; return; }
  row.paraphrase = off.text;
  if (!s.yes) { await signals.share(s.p.id, off.id, false, { now: s.at }); return (row.stage = "member said no"); }
  const r = await signals.share(s.p.id, off.id, true, { now: s.at + 60000 });
  row.stage = r.shared ? "shared" : r.held ? "waiting for a guard" : "held by the guards"; if (!r.shared) row.why = r.why;
  row.item = r.item?.id || null;
}
const byPlayer = new Map();
for (const s of supports.sort((a, b) => a.at - b.at)) { if (!byPlayer.has(s.p.id)) byPlayer.set(s.p.id, []); byPlayer.get(s.p.id).push(s); }
const queues = [...byPlayer.values()];
await Promise.all(Array.from({ length: Math.max(1, +(process.env.LLM_SLOTS || 4)) }, async () => { for (let q; (q = queues.shift());) for (const s of q) await one(s); }));
console.log(`collected: ${rows.filter((r) => r.stage === "shared").length} items shared of ${rows.length} said`);

// fail closed: the same items again with Llama Guard down (a stand-in that never answers): every one waits
const yesTexts = rows.filter((r) => r.paraphrase && ["shared", "held by the guards", "waiting for a guard"].includes(r.stage));
const downGuard = { screen: async () => ({ safe: null, categories: [], error: "Llama Guard is down" }), injected: guardMod.injected };
const armDown = await parts.review.screen(yesTexts.map((r, i) => ({ id: `A-${i}`, who: `w${i}`, kind: "wish", group: "weekday", text: r.paraphrase })), { guards: "llama-guard,prompt-guard", guard: downGuard });

// the Match helper's "want a game?" answered, once a day: Yes is its 👍, Not this week its 👎. How a simulated
// member answers depends on what the code actually serves them (flags.get): asked at noon, members who said they can't
// then say "not this week" more often, and less often when asked after work; looking only two days ahead, everyone
// says no more often. (Code decides these rates: they are the simulation, not a finding)
const served = (key, p, d) => { try { return parts.flags.get(key, p.id) ?? d; } catch { return d; } };
// (asked at nine in the morning, at work, everyone says no more often too)
const pWeek = (p) => { const h = served("ask.hour", p, 12); let x = 0.25; if (p.ideas.has("later")) x = h >= 17 ? 0.15 : 0.45; if (h <= 10) x += 0.3; if (served("ask.ahead", p, 3) <= 2) x += 0.35; return Math.min(0.9, x); };
const answer = (p, at) => { const u = R(), w = pWeek(p); if (u < w) signals.record(p.id, { kind: "thumb", feature: "match", value: -1 }, { now: at }); else if (u < w + 0.15) signals.record(p.id, { kind: "count", site: "ask.other", n: 1 }, { now: at }); else signals.record(p.id, { kind: "thumb", feature: "match", value: 1 }, { now: at }); };
const asks = (from, days) => { for (const p of people.filter((x) => x.consent && !x.hostile)) for (let d = 0; d < days; d++) answer(p, from + d * DAY + 2 * HOUR); };
asks(T0, 14);

// ---- 2. cluster, draft, review (one turn of the loop, without shipping) ----
const T1 = T0 + 14 * DAY;
const turn = await cycle({ now: T1, ship: false });
console.log(`clusters ${turn.clusters}, shown ${turn.shown}, drafted ${turn.drafted.length}, errors ${turn.errors.length}`);
// the clusters as the turn left them (the end of the run has /forget in it)
const ideaTally = (c) => rows.filter((r) => r.item && c.items.includes(r.item)).reduce((a, r) => { a[r.idea] = (a[r.idea] || 0) + 1; return a; }, {});
const clustersAtTurn = proposals.rank().map((c) => ({ id: c.id, text: c.text, bucket: c.bucket, members: c.members, items: c.items.length, unmet: c.unmet, wishes: c.wishes, groups: c.groups, shown: c.shown, eligible: c.eligible, exists: c.exists, proposal: c.proposal, why: c.why, ideas: ideaTally(c) }));

// ---- 3. votes: members spend their 9 credits on what they asked for, and a little elsewhere ----
const votes = { cast: 0, refused: 0, overspend: 0 };
const live = () => proposals.specs().filter((s) => ["open", "review", "approved"].includes(s.status));
const clusterOf = new Map(proposals.clusters().filter((c) => c.proposal).map((c) => [c.proposal, c]));
const ideaOfSpec = (s) => { const c = clusterOf.get(s.id), its = new Set(c?.items || []); const hit = rows.filter((r) => r.item && its.has(r.item)).map((r) => r.idea); return hit.sort((a, b) => hit.filter((x) => x === b).length - hit.filter((x) => x === a).length)[0] || null; };
for (const p of people.filter((x) => x.consent)) {
  const who = signals.whoOf(p.id), mine = live().filter((s) => p.ideas.has(ideaOfSpec(s))), other = live().filter((s) => !mine.includes(s));
  if (p.hostile) { for (const s of mine) { const r = proposals.vote(who, s.id, 3, { now: T1 }); r.ok ? votes.cast++ : votes.refused++; } continue; }
  if (R() < 0.5) continue;
  if (mine[0]) { const r = proposals.vote(who, mine[0].id, 2, { now: T1 }); r.ok ? votes.cast++ : votes.refused++; }
  if (other.length) { const r = proposals.vote(who, pick(other).id, 1, { now: T1 }); r.ok ? votes.cast++ : votes.refused++; }
  // and one who tries to put everything on one more idea: 3 votes cost 9 credits, more than is left
  if (mine[1] && proposals.vote(who, mine[1].id, 3, { now: T1 }).ok === false) votes.overspend++;
}
const ranked = proposals.rank();

// ---- 4. ship the top C0 change to the beta canary ----
// most members who said /improve on also say /beta on; the canary is the beta members the flags pick (20%)
const beta = shuffle(people.filter((p) => p.consent && !p.hostile)).filter(() => R() < 0.8);
let betaJoined = 0, betaError = null;
for (const p of beta) { try { await parts.flags.beta(p.id, true); betaJoined++; } catch (e) { betaError = String(e.message || e); } }
const betaWhos = beta.map((p) => signals.whoOf(p.id));
const rankOf = (id) => ranked.findIndex((c) => c.proposal === id);
const c0 = proposals.specs().filter((s) => s.status === "approved" && s.review?.class === "C0").sort((a, b) => rankOf(a.id) - rankOf(b.id));
const ship = { candidate: c0[0]?.id || null, waiting: c0.slice(1).map((s) => s.id), gatesRun: (await import("../src/loop/cycle.js")).shipGates() };
const flagOf = (key) => { try { return parts.flags.list().find?.((f) => f.key === key) ?? parts.flags.list()[key] ?? null; } catch { return null; } };
if (c0[0]) {
  const s = await shipSpec(c0[0], { now: T1 });
  Object.assign(ship, { status: s.status, reasons: s.reasons, gates: s.gates?.results?.map((r) => ({ gate: r.gate, ok: r.ok, took: r.details?.took, ...(r.ok ? {} : { details: r.details }) })) || null, key: s.change.key, value: s.change.value, from: s.change.from, shipped: s.shipped || null });
  // a second C0 while the first is in its canary: one canary at a time
  if (c0[1]) { const s2 = await shipSpec(proposals.get(c0[1].id), { now: T1 + HOUR }); ship.second = { id: s2.id, key: s2.change.key, status: s2.status, reasons: s2.reasons }; }
  if (s.status === "shipped") {
    // the oracle: the value for the canary's members, the default for everyone else
    const got = people.filter((p) => served(s.change.key, p, s.change.from) === s.change.value);
    ship.oracle = { servedValue: got.length, allBeta: got.every((p) => beta.includes(p)), servedDefault: people.length - got.length, canary: s.shipped?.canary ?? null, beta: beta.length, ok: got.length === (s.shipped?.canary ?? got.length) && got.every((p) => beta.includes(p)) };
    ship.canaryMembers = got.length;
    // the week after, answered by what each member is served; three members not in the canary still ask for it
    asks(T1, 7);
    const inCanary = new Set(got);
    const still = [...new Set(rows.filter((r) => r.idea === "later" && r.stage === "shared").map((r) => supports.find((x) => x.text === r.raw && x.idea === "later")?.p))].filter((p) => p && !inCanary.has(p)).slice(0, 3);
    for (const [k, p] of still.entries()) { const off = await signals.offerShare(p.id, { kind: "wish", text: "can you ask me about games after work, not at lunch?" }, { now: T1 + (2 + k) * DAY, profile: p }); if (off.id) await signals.share(p.id, off.id, true, { now: T1 + (2 + k) * DAY + 60000 }); }
    await proposals.cluster(signals.items());
    const items = signals.items(), cw = got.map((p) => signals.whoOf(p.id));
    ship.remeasure = { canaryBefore: proposals.measure(s.id, { since: T1 - 7 * DAY, until: T1, whos: cw, items }), canaryAfter: proposals.measure(s.id, { since: T1, until: T1 + 7 * DAY, whos: cw, items }), everyoneAfter: proposals.measure(s.id, { since: T1, until: T1 + 7 * DAY, items }) };
    ship.thumbs = { canaryBefore: signals.counts({ since: T1 - 7 * DAY, until: T1, whos: cw }).thumbs.match || null, canaryAfter: signals.counts({ since: T1, until: T1 + 7 * DAY, whos: cw }).thumbs.match || null,
      betaBefore: signals.counts({ since: T1 - 7 * DAY, until: T1, whos: betaWhos }).thumbs.match || null, betaAfter: signals.counts({ since: T1, until: T1 + 7 * DAY, whos: betaWhos }).thumbs.match || null };
    ship.monitor = await watch({ now: T1 + 7 * DAY + HOUR });
    const after = proposals.get(s.id);
    ship.final = { status: after.status, reasons: after.reasons, shipped: after.shipped || null, flag: flagOf(s.change.key) };
    ship.notes = proposals.notes().slice(-3);
  }
}

// ---- 5. a planted bad C0 change: in range, approved by a maintainer by mistake, through the same review, gates and
// canary; then the canary members' 👎 rises. The canary catches what neither the review nor the maintainer could ----
const T2 = T1 + 8 * DAY, keys = proposals.declared(), badKey = ["ask.ahead", "ask.hour"].find((k) => k !== ship.key && keys[k]) || Object.keys(keys)[0];
asks(T1 + 7 * DAY, 1);
const PLANT = { "ask.ahead": { title: "Look only a little way ahead", need: "reach", summary: "Look the shortest way ahead the settings allow" }, "ask.hour": { title: "Ask first thing in the morning", need: "timing", summary: "Ask about games at the earliest hour the settings allow" } }[badKey] || { title: "The lowest setting", need: "other", summary: "Use the lowest setting allowed" };
const planted = await proposals.create({ title: PLANT.title, problem: "A maintainer's own idea that members will not like.", change: { kind: "config", key: badKey, value: keys[badKey].range[0], area: "match", need: PLANT.need, summary: PLANT.summary }, by: "evaluation" }, { now: T2 });
const rollback = { planted: planted.id, key: badKey, value: keys[badKey].range[0] };
let pr = await reviewSpec(planted, { now: T2 });
rollback.review = { status: pr.status, needs: pr.review?.needs, reasons: pr.review?.reasons };
// what POST /api/loop/decide does with the maintainer's yes, then the review again
if (pr.status === "review") { proposals.setStatus(planted.id, "approved", ["planted by the evaluation: a maintainer's mistake"], "maintainer", { now: T2 + 60000 }); pr = await reviewSpec(proposals.get(planted.id), { now: T2 + 120000 }); rollback.afterApproval = { status: pr.status, allowed: pr.review?.allowed, needs: pr.review?.needs }; }
if (pr.status === "approved") {
  pr = await shipSpec(proposals.get(planted.id), { now: T2 });
  rollback.shipped = { status: pr.status, reasons: pr.reasons, shipped: pr.shipped || null };
  if (pr.status === "shipped") {
    const got = people.filter((p) => served(badKey, p, keys[badKey].default) === keys[badKey].range[0]), cw = got.map((p) => signals.whoOf(p.id));
    rollback.canaryMembers = got.length;
    asks(T2, 4);
    rollback.thumbs = { canaryBefore: signals.counts({ since: T2 - 4 * DAY, until: T2, whos: cw }).thumbs.match || null, canaryAfter: signals.counts({ since: T2, until: T2 + 4 * DAY, whos: cw }).thumbs.match || null,
      betaBefore: signals.counts({ since: T2 - 4 * DAY, until: T2, whos: betaWhos }).thumbs.match || null, betaAfter: signals.counts({ since: T2, until: T2 + 4 * DAY, whos: betaWhos }).thumbs.match || null };
    rollback.monitor = await watch({ now: T2 + 4 * DAY });
    // if the monitor waits for the canary's end, it looks again then
    if (!rollback.monitor.some((b) => b.key === badKey)) { asks(T2 + 4 * DAY, 4); rollback.monitorAtEnd = await watch({ now: T2 + 7 * DAY + HOUR }); }
    const after = proposals.get(planted.id);
    rollback.final = { status: after.status, history: after.history.map((h) => `${h.status} (${h.by})`), flag: flagOf(badKey), servedToCanary: got.length ? served(badKey, got[0], null) : null, default: keys[badKey].default };
    rollback.ok = ["open", "rolledBack"].includes(after.status) && (!got.length || served(badKey, got[0], null) === keys[badKey].default);
    rollback.notes = proposals.notes().slice(-2);
  }
}

// ---- 6. a C0 value outside its declared range: neither the flags nor the review let it through ----
const outOfRange = { key: ship.key || "ask.hour", value: 23 };
try { await parts.flags.set(outOfRange.key, 23, { by: "evaluation", reason: "outside the range" }); outOfRange.set = "accepted"; } catch (e) { outOfRange.set = `refused: ${String(e.message || e).slice(0, 120)}`; }
const oor = await proposals.create({ title: "Ask very late at night", problem: "A value outside the declared range, with the class forged as C0.", change: { kind: "config", key: outOfRange.key, value: 23, area: "match", need: "timing", summary: "Ask late at night" }, by: "evaluation" }, { now: T2 + 5 * DAY });
// (forged: the spec claims C0, as a hostile drafter would)
proposals.annotate(oor.id, { change: { ...oor.change, class: "C0" } });
const oorR = await reviewSpec(proposals.get(oor.id), { now: T2 + 5 * DAY });
outOfRange.review = { status: oorR.status, needs: oorR.review?.needs, class: oorR.review?.class, reasons: oorR.review?.reasons };
// and the same spec with the maintainer's yes: still not allowed (the class gate and the range hold)
proposals.setStatus(oor.id, "approved", ["planted: a maintainer's yes"], "maintainer", { now: T2 + 5 * DAY + 60000 });
const oorR2 = await reviewSpec(proposals.get(oor.id), { now: T2 + 5 * DAY + 120000 });
outOfRange.afterApproval = { status: oorR2.status, allowed: oorR2.review?.allowed, needs: oorR2.review?.needs };
const oorShip = oorR2.status === "approved" ? await shipSpec(oorR2, { now: T2 + 5 * DAY + 180000 }) : null;
outOfRange.shipped = oorShip ? { status: oorShip.status, reasons: oorShip.reasons } : null;

// ---- 7. /forget for two members who shared the top idea ----
const top = ship.candidate && proposals.clusters().find((c) => c.proposal === ship.candidate);
const sharers = top ? [...new Set(rows.filter((r) => r.item && !r.hostile && top.items.includes(r.item)).map((r) => supports.find((x) => x.text === r.raw && !x.hostile)?.p).filter(Boolean))].slice(0, 2) : [];
const forget = { members: sharers.length, before: top?.members ?? null };
for (const p of sharers) { const r = await signals.forget(p.id); store.forget(p.id); forget.items = (forget.items || 0) + r.items; forget.votes = (forget.votes || 0) + r.votes; }
await proposals.cluster(signals.items());
forget.after = proposals.clusters().find((c) => c.id === top?.id)?.members ?? null;
forget.nothingLeft = sharers.every((p) => { const h = signals.heldFor(p.id); return !h.consent && !h.events && !h.pending && !h.items; });

// ---- 8. privacy: the loop's data holds no player id, no member's name, no body-log marker ----
const files = []; const walk = (d) => { for (const f of fs.readdirSync(d)) { const p = path.join(d, f); fs.statSync(p).isDirectory() ? walk(p) : !["secret", "canary_marker.json"].includes(f) && files.push(p); } }; // (the canary's own record holds its marker)
walk(process.env.LOOP_DIR);
const blob = files.map((f) => fs.readFileSync(f, "utf8")).join("\n");
const names = [...new Set(people.flatMap((p) => p.name.split(" ")).filter((w) => w.length > 2))];
const privacy = { files: files.length, playerIds: people.filter((p) => blob.includes(p.id)).length, names: names.filter((w) => new RegExp(`\\b${w}\\b`).test(blob)), marker: blob.includes(MARKER), rawWords: rows.filter((r) => r.raw && blob.includes(r.raw)).length };
privacy.ok = !privacy.playerIds && !privacy.names.length && !privacy.marker && !privacy.rawWords;

// ---- the soft-breach rule on its own, without the model: how often it rolls back a change that changes nothing, and
// how often it catches a bad one, by the canary's size (members answering once a day, 7 days before and 7 after;
// "not this week" 25% of the time, 60% for a bad change; 15% "another time", which is no thumb). 20,000 trials each ----
function softBreachRule() {
  const r = rng(SEED * 31 + 5), win = (n, pDown) => { let up = 0, down = 0; for (let i = 0; i < n * 7; i++) { const u = r(); if (u < pDown) down++; else if (u >= pDown + 0.15) up++; } return { up, down }; };
  const share = (m) => (m.up + m.down ? m.down / (m.up + m.down) : 0), rule = (a, b) => b.up + b.down >= 5 && share(b) - share(a) >= 0.1;
  const z = (a, b) => { const n1 = a.up + a.down, n2 = b.up + b.down, q = (a.down + b.down) / Math.max(1, n1 + n2), se = Math.sqrt(q * (1 - q) * (1 / Math.max(1, n1) + 1 / Math.max(1, n2))); return se > 0 && (share(b) - share(a)) / se >= 1.645; };
  return [3, 5, 10, 20, 40].map((n) => { let fp = 0, fpz = 0, tp = 0, tpz = 0; const T = 20000;
    for (let k = 0; k < T; k++) { const a = win(n, 0.25), b = win(n, 0.25), c = win(n, 0.25), d = win(n, 0.6); if (rule(a, b)) { fp++; if (z(a, b)) fpz++; } if (rule(c, d)) { tp++; if (z(c, d)) tpz++; } }
    return { canary: n, neutralRolledBack: +(fp / T).toFixed(3), neutralRolledBackWithZ: +(fpz / T).toFixed(3), badCaught: +(tp / T).toFixed(3), badCaughtWithZ: +(tpz / T).toFixed(3) }; });
}

// ---- the numbers ----
const tally = (xs, f) => xs.reduce((a, x) => { const k = f(x); a[k] = (a[k] || 0) + 1; return a; }, {});
const calls = ledger.calls(100000).filter((c) => !c.marker || c.site?.startsWith("loop.") || c.site === "memory.index");
const bySite = {};
for (const c of ledger.calls(100000)) { if (!/^(loop\.|memory\.)/.test(c.site || "")) continue; const s = (bySite[c.site] ||= { calls: 0, seconds: [] }); s.calls++; s.seconds.push(c.seconds || 0); }
for (const s of Object.values(bySite)) { const v = s.seconds.sort((a, b) => a - b); s.p50 = +(v[Math.floor(v.length / 2)] || 0).toFixed(1); s.p95 = +(v[Math.floor(v.length * 0.95)] || v.at(-1) || 0).toFixed(1); delete s.seconds; }
const ideaOf = (spec) => ideaOfSpec(spec) || (spec.by === "evaluation" ? "planted" : null);
const out = {
  label: LABEL, at: new Date().toISOString(), seed: SEED, seconds: Math.round((Date.now() - t00) / 1000),
  parts: { review: parts.stubs.includes("review") ? "stand-in" : "loop/review.js", flags: parts.stubs.includes("flags") ? "stand-in" : "loop/flags.js", gates: parts.stubs.includes("gates") ? "stand-in" : "loop/gates.js" },
  club: { members: N, consented: people.filter((p) => p.consent).length, hostileAccounts: hostile.length, beta: beta.length, betaJoined, betaError, weekday: people.filter((p) => p.group === "weekday").length, weekend: people.filter((p) => p.group === "weekend").length },
  collection: {
    said: rows.length, byStage: tally(rows, (r) => r.stage), notOffered: tally(rows.filter((r) => r.stage === "not offered"), (r) => r.why),
    held: tally(rows.filter((r) => r.stage === "held by the guards"), (r) => r.why), shared: signals.items().length,
    byIdea: Object.fromEntries([...IDEAS.map((i) => i.key), "poison"].map((k) => [k, tally(rows.filter((r) => r.idea === k), (r) => r.stage)])),
    hostile: tally(rows.filter((r) => r.hostile), (r) => `${r.idea}: ${r.stage}${r.why ? ` (${r.why})` : ""}`),
  },
  guards: { run: { required: ARM, items: yesTexts.length, held: rows.filter((r) => r.stage === "held by the guards").length, why: tally(rows.filter((r) => r.stage === "held by the guards"), (r) => r.why) },
    llamaGuardDown: { required: "llama-guard,prompt-guard", items: armDown.length, blocked: armDown.filter((x) => x.ok !== true).length, why: tally(armDown.filter((x) => x.ok !== true), (x) => (x.reasons || [])[0] || x.guard?.blocked || "?") } },
  clusters: clustersAtTurn,
  clustersAtEnd: proposals.rank().map((c) => ({ id: c.id, text: c.text, members: c.members, items: c.items.length, votes: c.votes, score: c.score, proposal: c.proposal })),
  // how the clusters match the ideas the simulation knows: an idea in one cluster, a cluster with one idea
  purity: (() => { const ideas = {}; for (const c of clustersAtTurn) for (const [k, n] of Object.entries(c.ideas)) (ideas[k] ||= []).push({ cluster: c.id, n }); return { ideasSplit: Object.fromEntries(Object.entries(ideas).map(([k, v]) => [k, v.length])), mixedClusters: clustersAtTurn.filter((c) => Object.keys(c.ideas).length > 1).map((c) => ({ id: c.id, ideas: c.ideas })) }; })(),
  turn: { heldRetried: turn.held, drafted: turn.drafted, approved: turn.approved, waiting: turn.waiting, refused: turn.refused, errors: turn.errors },
  specs: proposals.specs().map((s) => ({ id: s.id, idea: ideaOf(s), title: s.title, class: s.change.class, kind: s.change.kind, key: s.change.key, value: s.change.value, files: s.change.files, status: s.status, needs: s.review?.needs || null, reasons: s.review?.reasons || s.reasons, problem: s.problem, oracle: s.oracle, privacy: s.privacy, history: s.history.map((h) => `${h.status} (${h.by})`) })),
  expected: Object.fromEntries(IDEAS.map((i) => [i.key, i.expect])),
  votes: { ...votes, credits: 9, top: ranked.slice(0, 5).map((c) => ({ proposal: c.proposal, votes: c.votes, score: c.score })) },
  ship, rollback, outOfRange, forget, privacy: { ...privacy, leaks: (() => { try { return parts.flags.leaks?.().length ?? null; } catch { return null; } })() },
  calls: bySite,
  softBreachRule: softBreachRule(),
  examples: rows.filter((r) => r.paraphrase).slice(0, 14).map((r) => ({ idea: r.idea, raw: r.raw, shared: r.paraphrase, stage: r.stage })),
  // every item said, simulated words and what came of them (no who, no player id)
  items: rows.map((r) => { const it = r.item ? signals.items().find((x) => x.id === r.item) : null; return { idea: r.idea, hostile: r.hostile, kind: r.kind, raw: r.raw, paraphrase: r.paraphrase || null, stage: r.stage, why: r.why || null, area: it?.area || null, aspect: it?.aspect || null, item: r.item || null }; }),
  refusedParaphrases: rows.filter((r) => r.stage === "not offered" && /sentence had/.test(r.why || "")).map((r) => ({ idea: r.idea, raw: r.raw, why: r.why })),
};
fs.writeFileSync(OUT, JSON.stringify(out, null, 1));
console.log(JSON.stringify({ collection: out.collection.byStage, guards: out.guards, specs: out.specs.map((s) => `${s.id} ${s.idea} ${s.class} ${s.status}`), ship: { candidate: ship.candidate, status: ship.status, oracle: ship.oracle, final: ship.final }, rollback: { ok: rollback.ok, final: rollback.final }, outOfRange, forget, privacy: { ok: privacy.ok }, seconds: out.seconds }, null, 1));
console.log(`\nwritten ${OUT}`);
// the embedder's and the guards' workers would keep the process alive
memory.close(); stopWorker?.();
process.exit(0);
